SELECT data_type, count(*) FROM information_schema.columns WHERE table_name='configurations' GROUP BY data_type ORDER BY 2 DESC; SELECT 'total', count(*) FROM information_schema.columns WHERE table_name='configurations'; SELECT 'array', count(*) FROM information_schema.columns WHERE table_name='configurations' AND data_type='ARRAY'; SELECT 'tables', count(*) FROM information_schema.tables WHERE table_schema='public';
